window.NARRATION = {"ci_a": {"dur": 22.72, "text": "Pressure shows how you actually lead. This is where you start to see the gap between instinct and intention. Take about 30 seconds on each of these. Write what actually went on inside you, rather than what you think should have happened. Only you can see what you write, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead.", 0], [2.93, "This is where you start to see the gap between instinct and intention.", 0], [7.35, "Take about 30 seconds on each of these.", 1], [9.97, "Write what actually went on inside you, rather than what you think should have happened.", 1], [14.69, "Only you can see what you write, and it's saved here so you can come back to it.", 1], [19.05, "Select Save on each one as you go, then select Next.", 2]], "v": "k1", "cues": [0.03, 7.35, 19.05]}, "ci_b": {"dur": 10.8, "text": "Now look at what you wrote and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", "sents": [[0.01, "Now look at what you wrote and pick the pattern that's closest to it.", 0], [3.75, "There's no right answer.", 1], [5.23, "Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", 1]], "v": "k1", "cues": [0.01, 3.75]}, "ci_c": {"dur": 20.08, "text": "Now run the Foundation Reset. Say your five words, the ones you saved on the Foundation Reset screen. Ask yourself for two next-best steps. Pick the one you'll take in the next ten minutes. Then take one breath and answer the anchor on the last card. It takes about a minute and works best standing up, so do it now before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.15, "Say your five words, the ones you saved on the Foundation Reset screen.", 1], [6.37, "Ask yourself for two next-best steps.", 1], [9.07, "Pick the one you'll take in the next ten minutes.", 1], [11.71, "Then take one breath and answer the anchor on the last card.", 1], [15.41, "It takes about a minute and works best standing up, so do it now before you move on.", 2]], "v": "k1", "cues": [0, 2.15, 15.41]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "v4l", "cues": [0.05]}, "n_5_14": {"dur": 10.08, "text": "Time for the drill. This one puts you in a disagreement in front of other people. Press Play. The video pauses a few times so you can answer, and it resumes when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.59, "This one puts you in a disagreement in front of other people.", 0], [4.89, "Press Play.", 1], [5.97, "The video pauses a few times so you can answer, and it resumes when you're done.", 1]], "v": "k1", "cues": [0.01, 4.89]}, "pc_n_5_0": {"dur": 11.76, "text": "Lesson 5 is about lasting the whole season. You'll look at your own energy first, then at what your team copies from you and how you lead them through recovery. Select Start Lesson.", "sents": [[0.01, "Lesson 5 is about lasting the whole season.", 0], [3.63, "You'll look at your own energy first, then at what your team copies from you and how you lead them through recovery.", 1], [10.37, "Select Start Lesson.", 1]], "v": "r3L", "cues": [0.01, 3.63]}, "pc_n_5_1": {"dur": 14.48, "text": "Read this moment. Which message do you think your team heard? Teams copy what their leader does far more than what the leader says. This lesson starts with your own energy, then moves to one practice your team will see you maintain.", "sents": [[0, "Read this moment.", 0], [1.73, "Which message do you think your team heard?", 0], [4.33, "Teams copy what their leader does far more than what the leader says.", 1], [8.67, "This lesson starts with your own energy, then moves to one practice your team will see you maintain.", 1]], "v": "pc1", "cues": [0, 4.33]}, "pc_n_5_11": {"dur": 24.0, "text": "Here's the recovery session from the video, in order. Start by celebrating the wins, specifically and by name. Then capture the lessons: what worked and what you'd change next time. Give something back. The manager in the video gave everyone an extra half day. Only then do you plan the next push. The order matters because it shows the team that recovery is real.", "sents": [[0.03, "Here's the recovery session from the video, in order.", 0], [3.19, "Start by celebrating the wins, specifically and by name.", 1], [7.83, "Then capture the lessons: what worked and what you'd change next time.", 2], [12.39, "Give something back.", 3], [13.95, "The manager in the video gave everyone an extra half day.", 3], [17.47, "Only then do you plan the next push.", 4], [20.03, "The order matters because it shows the team that recovery is real.", 4]], "v": "r3L", "cues": [0.03, 3.19, 7.83, 12.39, 17.47]}, "pc_n_5_12": {"dur": 6.8, "text": "Let's put the recovery session under deadline pressure. Choose the first meeting you'd hold, and you'll hear where it leads.", "sents": [[0, "Let's put the recovery session under deadline pressure.", 0], [3.37, "Choose the first meeting you'd hold, and you'll hear where it leads.", 1]], "v": "r3L", "cues": [0, 3.37]}, "pc_n_5_12_o0": {"dur": 11.12, "text": "The plan gets done, and the team learns that finishing hard is followed by starting hard. That's how burnout becomes normal, one meeting at a time. Try the other option to compare.", "sents": [[0.05, "The plan gets done, and the team learns that finishing hard is followed by starting hard.", 0], [5.81, "That's how burnout becomes normal, one meeting at a time.", 0], [9.43, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_5_12_o1": {"dur": 8.24, "text": "The plan still gets done by Friday. It's written by a team that believes recovery is real, because they just watched you make time for it.", "sents": [[0.05, "The plan still gets done by Friday.", 0], [2.71, "It's written by a team that believes recovery is real, because they just watched you make time for it.", 0]], "v": "r3L", "cues": [0.05]}, "pc_n_5_14": {"dur": 31.6, "text": "Your core rep this week is your energy audit, which takes about fifteen minutes. Track your energy for one day, note what drained you and what fueled you, and then protect one block on next week's calendar. If you have more time, choose one practice your team will see you keep and write the sentence you'll use to explain it. And plan the recovery session for after your next big deadline: wins, lessons, and what you'll give back. Run your core rep, then ask one person how it landed. Select Open your Lesson 5 pages to get started.", "sents": [[0.01, "Your core rep this week is your energy audit, which takes about fifteen minutes.", 0], [4.95, "Track your energy for one day, note what drained you and what fueled you, and then protect one block on next week's calendar.", 0], [12.27, "If you have more time, choose one practice your team will see you keep and write the sentence you'll use to explain it.", 1], [18.57, "And plan the recovery session for after your next big deadline: wins, lessons, and what you'll give back.", 2], [25.25, "Run your core rep, then ask one person how it landed.", 3], [28.63, "Select Open your Lesson 5 pages to get started.", 3]], "v": "pc1", "cues": [0.01, 12.27, 18.57, 25.25]}, "pc_n_5_15": {"dur": 12.48, "text": "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst. She's a professional athlete and the founder of RyFit International, and she takes a whole-life approach to performance. Press Play to hear from her.", "sents": [[0, "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst.", 0], [4.57, "She's a professional athlete and the founder of RyFit International, and she takes a whole-life approach to performance.", 1], [11.17, "Press Play to hear from her.", 1]], "v": "pc1", "cues": [0, 4.57]}, "pc_n_5_16": {"dur": 12.96, "text": "Ryall's drill checks whether your pace is sustainable. It takes three minutes. Select Start the timer and work through each step. When you've completed the drill or scheduled a time to run it, select the option that fits.", "sents": [[0, "Ryall's drill checks whether your pace is sustainable.", 0], [3.23, "It takes three minutes.", 0], [4.79, "Select Start the timer and work through each step.", 1], [8.17, "When you've completed the drill or scheduled a time to run it, select the option that fits.", 1]], "v": "pc1", "cues": [0, 4.79]}, "pc_n_5_18_q0": {"dur": 7.84, "text": "A few questions on the main ideas. First: which of these is modeling a sustainable practice, rather than announcing one?", "sents": [[0, "A few questions on the main ideas.", 0], [2.25, "First: which of these is modeling a sustainable practice, rather than announcing one?", 0]], "v": "r3L", "cues": [0]}, "pc_n_5_18_q1": {"dur": 3.76, "text": "What does managing energy, rather than time, look like?", "sents": [[0.05, "What does managing energy, rather than time, look like?", 0]], "v": "r3", "cues": [0.05]}, "pc_n_5_18_q2": {"dur": 3.12, "text": "After a brutal quarter, what comes first?", "sents": [[0, "After a brutal quarter, what comes first?", 0]], "v": "r3", "cues": [0]}, "pc_n_5_18_q3": {"dur": 7.28, "text": "Last one. Your star player works constantly and you're worried about burnout. What's the best opening?", "sents": [[0.15, "Last one.", 0], [1.35, "Your star player works constantly and you're worried about burnout.", 0], [5.91, "What's the best opening?", 0]], "v": "r3L", "cues": [0.15]}, "pc_n_5_18_w0": {"dur": 9.68, "text": "Your team copies what you do. When they see you keep a practice and hear why, it becomes permission. Words alone get canceled by the late-night email.", "sents": [[0.05, "Your team copies what you do.", 0], [2.43, "When they see you keep a practice and hear why, it becomes permission.", 0], [6.71, "Words alone get canceled by the late-night email.", 0]], "v": "r3", "cues": [0.05]}, "pc_n_5_18_w1": {"dur": 8.16, "text": "You schedule your hardest work for your best hours and build recovery in, like the executive with ninety minutes of deep work and two short breaks.", "sents": [[0, "You schedule your hardest work for your best hours and build recovery in, like the executive with ninety minutes of deep work and two short breaks.", 0]], "v": "r3L", "cues": [0]}, "pc_n_5_18_w2": {"dur": 8.32, "text": "Celebrate, capture the lessons, and give something back, then plan. The order shows the team that recovery is real.", "sents": [[0.05, "Celebrate, capture the lessons, and give something back, then plan.", 0], [5.13, "The order shows the team that recovery is real.", 0]], "v": "r3L", "cues": [0.05]}, "pc_n_5_18_w3": {"dur": 7.2, "text": "Recognizing their dedication keeps it safe to talk about. Asking how they'll sustain it makes them part of the solution.", "sents": [[0.03, "Recognizing their dedication keeps it safe to talk about.", 0], [3.87, "Asking how they'll sustain it makes them part of the solution.", 0]], "v": "r3", "cues": [0.03]}, "pc_n_5_19": {"dur": 31.92, "text": "Before you go, here's what to keep from this lesson. Protect your best hours. One deep-work block and one recovery block on the calendar are a good start. Your team copies what you do, so pick one practice they'll see you keep and say why. And after a hard stretch, recover first: celebrate the wins, capture the lessons, and give something back. Then plan. Select Download my answers for a Word document containing what you wrote today. Chapter 10 of the book is about sustaining your energy.", "sents": [[0.03, "Before you go, here's what to keep from this lesson.", 0], [3.39, "Protect your best hours.", 1], [5.57, "One deep-work block and one recovery block on the calendar are a good start.", 1], [10.23, "Your team copies what you do, so pick one practice they'll see you keep and say why.", 2], [15.59, "And after a hard stretch, recover first: celebrate the wins, capture the lessons, and give something back.", 3], [22.73, "Then plan.", 3], [24.23, "Select Download my answers for a Word document containing what you wrote today.", 4], [28.73, "Chapter 10 of the book is about sustaining your energy.", 4]], "v": "pc1", "cues": [0.03, 3.39, 10.23, 15.59, 24.23]}, "pc_n_5_20": {"dur": 18.32, "text": "That's Lesson 5 done. There's one lesson to go, and the championship round is next. This week, complete your core rep, your energy audit, and ask one person how it went. Next time is the final lesson, when you'll have the conversation that makes your Athleader's season visible. It's the big one.", "sents": [[0.03, "That's Lesson 5 done.", 0], [2.07, "There's one lesson to go, and the championship round is next.", 0], [5.93, "This week, complete your core rep, your energy audit, and ask one person how it went.", 1], [11.33, "Next time is the final lesson, when you'll have the conversation that makes your Athleader's season visible.", 1], [17.17, "It's the big one.", 1]], "v": "pc1", "cues": [0.03, 5.93]}, "pc_n_5_3": {"dur": 6.16, "text": "A quick look back at Lesson 4 before you start. Choose the answer you remember. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 4 before you start.", 0], [2.93, "Choose the answer you remember.", 1], [4.61, "This one isn't scored.", 1]], "v": "r3L", "cues": [0, 2.93]}, "pc_n_5_4": {"dur": 24.48, "text": "Here's what you'll practice in this lesson. You'll track your energy for a day and note what drains you and what fuels you. Based on that, you'll protect one block on next week's calendar for deep work or for recovery. You'll choose one sustainable practice your team will see you do and say out loud why you do it. And after the next hard stretch, you'll lead a recovery session before anyone plans the next push.", "sents": [[0.03, "Here's what you'll practice in this lesson.", 0], [2.35, "You'll track your energy for a day and note what drains you and what fuels you.", 1], [7.11, "Based on that, you'll protect one block on next week's calendar for deep work or for recovery.", 2], [12.99, "You'll choose one sustainable practice your team will see you do and say out loud why you do it.", 3], [18.55, "And after the next hard stretch, you'll lead a recovery session before anyone plans the next push.", 4]], "v": "pc1", "cues": [0.03, 2.35, 7.11, 12.99, 18.55]}, "pc_n_5_7": {"dur": 27.28, "text": "Here's the difference Melissa describes in the video. Managing time means filling every slot. Meetings run back-to-back, replies go out at all hours, and much of the day is spent working with little energy. Managing energy means protecting your best hours. The executive in the video blocks ninety minutes for deep work first thing and takes two short recovery breaks in the afternoon. She gets more done in six hours than most people do in ten.", "sents": [[0.03, "Here's the difference Melissa describes in the video.", 0], [2.97, "Managing time means filling every slot.", 1], [6.11, "Meetings run back-to-back, replies go out at all hours, and much of the day is spent working with little energy.", 1], [13.17, "Managing energy means protecting your best hours.", 2], [16.73, "The executive in the video blocks ninety minutes for deep work first thing and takes two short recovery breaks in the afternoon.", 2], [23.85, "She gets more done in six hours than most people do in ten.", 2]], "v": "pc1", "cues": [0.03, 2.97, 13.17]}, "pc_n_5_9": {"dur": 29.68, "text": "Here's the story from the video. A manager noticed his team sending emails at all hours, and people were getting worn down. In the next team meeting, he said he didn't expect replies outside work hours and asked everyone to use schedule-send for anything written after six. Then he did it himself. The team's habits changed because he named the practice and they could see him follow it. Your Playbook asks you to choose one practice like this for the week and write the sentence you'll use to introduce it.", "sents": [[0.01, "Here's the story from the video.", 0], [2.11, "A manager noticed his team sending emails at all hours, and people were getting worn down.", 1], [7.93, "In the next team meeting, he said he didn't expect replies outside work hours and asked everyone to use schedule-send for anything written after six.", 2], [16.63, "Then he did it himself.", 2], [17.21, "The team's habits changed because he named the practice and they could see him follow it.", 3], [23.63, "Your Playbook asks you to choose one practice like this for the week and write the sentence you'll use to introduce it.", 4]], "v": "pc1", "cues": [0.01, 2.11, 7.93, 17.21, 23.63]}, "r2_code_pulse": {"dur": 7.36, "text": "Type the code from the last page of the Pulse Check, then select Submit. A quick knowledge check comes next, then your recap.", "sents": [[0.01, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.23, "A quick knowledge check comes next, then your recap.", 0]], "v": "r3", "cues": [0.01]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_pulse": {"dur": 21.36, "text": "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season. It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next, and it opens right here.", "sents": [[0.01, "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season.", 0], [6.57, "It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks.", 1], [12.25, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [18.83, "Select Next, and it opens right here.", 2]], "v": "k1", "cues": [0.01, 6.57, 12.25]}};
